INSERT INTO manuals (id, machine_name) VALUES ('a1b2c3d4-0000-4000-8000-000000007502', $m$RICOH 7502$m$)
INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC101$m$, $m$D$m$, $m$Exposure Lamp Error$m$, $m$At trigger on, the lamp was not detected on.$m$, $m$SBU board defective · SIOB board defective · IPU board defective · BCU board defective · Exposure lamp defective · Lamp stabilizer defective · Lamp stabilizer harness damaged, disconnected · Standard white plate dirty, disconnected or has condensation · DF white belt dirty · DF glass dirty or has condensation · Scanner mirror dirty, out of position or has condensation · Lens dirty, out of position$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC120$m$, $m$D$m$, $m$Scanner home position error 1$m$, $m$The scanner HP sensor does not detect the OFF condition during initialization or copying.$m$, $m$BCU, SIOB defective · Scanner motor defective · Scanner HP sensor defective. · Harness between BCU, SIOB, scanner motor disconnected. · Harness between scanner HP sensor and BCU disconnected. · Scanner wire, timing belt, pulley, or carriage installed incorrectly.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC121$m$, $m$D$m$, $m$Scanner home position error 2$m$, $m$The scanner HP sensor does not detect the ON condition during Conditions initialization or copying.$m$, $m$BCU, SIOB defective · Scanner motor defective · Scanner HP sensor defective · Harness between BCU, SIOB, scanner motor disconnected · Harness between scanner HP sensor and BCU disconnected · Scanner wire, timing belt, pulley or carriage installed incorrectly. · Black level detection error · The black level cannot be adjusted within the target during auto gain · control.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC141$m$, NULL, $m$Harness between SBU ± SIOB is disconnected.$m$, $m$Harness between SIOB ± BCU is disconnected.$m$, $m$D Defective SBU · Defective BCU$m$, $m$Check the SBU-SIOB/SIOB-BCU harness connections or replace these harnesses. Replace the SBU. Replace the BCU$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC142$m$, $m$D$m$, $m$White level detection error$m$, $m$The white level cannot be adjusted to the second target level within the target during auto gain control.$m$, $m$Dirty exposure lamp or optics section · SBU board defective · SIOB defective · IPU board defective · BCU board defective · Harnesses are disconnected. · Exposure lamp defective · - Lamp stabilizer defective · Scanner motor defective$m$, $m$1. Clean the exposure glass, white plate, mirrors, and lens. 2. Check if the exposure lamp is lit during initialization. 3. Check the harness connection. 4. Replace the exposure lamp. 5. Replace the scanner motor. 6. Replace the SBU board, SIOB, IPU board or BCU board. SBU transmission error After the SBU switches on, the BCU detects one of the following D conditions on the SBU: 1 s after power on, the SYDO signal does not go high, even after 1 retry. 1 s after power on, the SYDO signal goes high, but the SBU ID$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC144$m$, NULL, $m$could not be read after 3 attempts.$m$, $m$SBU defective$m$, $m$SIOB defective · BCU defective · Harness between the SBU - SIOB is disconnected · Harness between the SIOB - BCU is disconnected · Harness between the SIOB ± PSU is disconnected$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC161-01$m$, $m$D$m$, $m$IPU error (LSYNC abnormal)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC161-02$m$, NULL, $m$The error result of self-diagnostic by the ASIC on the BICU is Service Call$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC161-03$m$, NULL, $m$detected. Conditions$m$, $m$Defective BICU$m$, $m$Defective connection between BICU and SBU$m$, $m$Check the connection between BICU and SBU. Replace the BICU. D IPU error (Ri response abnormal) The machine detects an error during an access to the Ri. Defective BICU board Replace the BICU board. D IPU error (Aruru operation abnormal) The IPU fails to configure or initialize the DRAM. Defective BICU board Replace the BICU board.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC165$m$, $m$D$m$, $m$Copy data security unit error$m$, $m$The copy data security option is installed by not operating correctly.$m$, $m$Copy data security card corrupted · The board is not installed or the board is defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC181$m$, $m$D$m$, $m$Inverter Fan Error$m$, $m$When the exposure lamp is triggered on, the inverter fan motor does not rotate.$m$, $m$SIOB defective · BCU defective · Inverter fan motor defective · Harness between the inverter fan motor - SIOB is disconnected · Harness between the SIOB ± BCU is disconnected · Harness between the SIOB ± PSU is disconnected$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC182$m$, $m$D$m$, $m$Scanner Fan Error: Right Side$m$, $m$The fan located on the right side of the exposure unit is not rotating.$m$, NULL, $m$Check the fan connections Fan defective Check SBU connection SBU defective$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC185$m$, $m$D$m$, $m$CIS transmission error$m$, $m$Error caused during ASIC register's automatic initialization on the CIS, or during transmission between the CIS ± DF. Harness between the CIS ± DF is disconnected CIS defective$m$, $m$CIS LED error$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC186$m$, NULL, $m$LED on the CIS causes error$m$, $m$During initializing, the ration of the average between leading-edge D area and rear-edge is beyond the permissible level (0.7 ± 1.43). During scanning, the shading data peak is under 32(8bit). Harness CN210 and CN220 on ADF are disconnected. Otherwise, replace CIS.$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC187$m$, NULL, $m$CIS BK level error$m$, $m$The BK level scanned by CIS is abnormal. The BK level average of R, G or B is/are not from 2 to 62. Service Call D 0 < Calibrated BK data level < 255(10bit). Conditions$m$, NULL, $m$Turn off the machine. Make sure CN210 and CN220 are connected firmly. Turn on the machine.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC188$m$, $m$D$m$, $m$CIS white level error$m$, $m$The shading data peak detected from the CIS is abnormal.$m$, $m$CIS defective$m$, $m$Make sure CN210 and CN220 are connected firmly. Replace the CIS.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC189$m$, NULL, $m$CIS gray balance adjustment error$m$, $m$The adjustment error occurs during the test after adjusting the gray balance. Retry the gray balance adjustment.$m$, $m$D · If the machine does not recover, do the following steps.$m$, $m$1. Turn off the machine. 2. Make sure CN210 and CN220 are connected firmly. 3. Turn on the machine. If the machine does not recover, replace the CIS.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC195$m$, $m$D$m$, $m$Machine serial number error$m$, $m$The number registered for the machine serial number does not match.$m$, NULL, $m$Confirm the correct serial number of the machine in the specifications. - Important: When SC195 occurs, the serial number must be input. Contact your technical supervisor.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC202$m$, $m$D$m$, $m$Polygon mirror motor error 1: Timeout at ON$m$, $m$The polygon mirror motor unit did not enter "Ready" status within 20 sec. after the motor was turned on, The polygon mirror motor PCB connector is loose, broken, or defective$m$, $m$- Polygon mirror motor PCB defective · Polygon mirror motor defective · IPU defective · Polygon mirror motor error 2: Timeout at OFF$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC203$m$, $m$D$m$, $m$The polygon mirror motor did not leave "Ready" within 3 sec. after the$m$, $m$motor was switched off. (The XSCRDY signal did not go HIGH (inactive) within 3 sec.)$m$, $m$The polygon mirror motor PCB connector is loose, broken, or · defective · - Polygon mirror motor PCB defective · Polygon mirror motor defective · IPU defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC204$m$, $m$D$m$, $m$Polygon mirror motor error 3: XSCRDY signal error$m$, $m$The polygon mirror motor "Ready" signal goes inactive (HIGH) while images are being produced or the synchronization signal is being output. Polygon mirror motor PCB connector loose, broken, defective - Polygon mirror motor PCB defective$m$, $m$Polygon mirror motor defective · Laser synchronization detection error$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC220$m$, $m$D$m$, $m$The 1st laser synchronization detection unit could not detect the line$m$, $m$synchronization signal (DETP0) within 500 ms while the polygon mirror Service Call motor was operating at normal speed. Note: The unit polls for the signal every 50 ms. This SC is issued after the 10th attempt fails to detect the signal. Laser synchronization board connector loose, broken, defective Laser synchronization detection board is not installed correctly (out - of alignment)$m$, $m$Laser synchronization board defective · IPU defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC221$m$, $m$D$m$, $m$Laser Synchronization Detector Error: K Leading Edge (LD1)$m$, $m$While the polygon motor is rotating normally, no synchronizing detection signal is output for black, leading edge for any LD other than LD0. Harness between the laser synchronizing detector and I/F unit is$m$, $m$disconnected, defective$m$, $m$Check all connections between LD unit, LDB, IPU LD unit LDB defective IPU defective FGATE ON error: K The PFGATE ON signal does not assert within 5 seconds after processing the image in normal job or MUSIC for start position [K].$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC230$m$, $m$D$m$, $m$Defective ASIC$m$, $m$Poor connection between controller and BICU.$m$, $m$Defective BICU$m$, $m$Check the connection between the controller board and the BICU. Replace the BICU. Replace the controller board. FGATE OFF Error: K$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC231$m$, $m$D$m$, $m$The PFGATE ON signal still asserts within 5 seconds after$m$, $m$processing the image in normal job or MUSIC for end position [K]. The PFGATE ON signal still asserts when the next job starts. See SC 230 for troubleshooting details.$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC240$m$, NULL, $m$LD error$m$, $m$The BICU detects LDB error a few times consecutively when LDB unit turns on after LDB initialization.$m$, $m$C Worn-out LD · Disconnected or broken harness of the LD$m$, $m$Replace the harness of the LD. Replace the laser optics housing unit. Replace the BICU. GAVD communication error A problem occurred in the GAVD or eSOC.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC270$m$, $m$D$m$, $m$Check connection points on the BCU, IPU for loose, broken, or$m$, $m$defective harness or connector$m$, $m$IPU defective · BCU defective · LDU effective · Charge corona output error · D The feedback voltage from the charge corona unit is detected too Service Call · high 9 times.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC300-00$m$, NULL, NULL, $m$Charge corona power pack defective$m$, $m$- Charge corona harness disconnected · Poor charge corona unit connection$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC305-00$m$, NULL, $m$Charge corona wire cleaner error 1$m$, $m$The charge cleaner pad does not arrive at the home position: D Motor locked within 4 s after switching on, or does not lock within 30 s. Motor locked within 10 s after reversing, or does not lock within 30 s.$m$, $m$Charge corona wire cleaner motor defective · Motor driver defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC306-00$m$, $m$C$m$, $m$Charge corona wire cleaner error 2$m$, $m$Charge corona motor is disconnected. (The current at the charge corona motor is detected less than 83 mA.) Charge corona wire cleaner motor connector is defective or disconnected.$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC307-00$m$, $m$D$m$, $m$Charge grid circuit open$m$, $m$When high voltage goes to the corona grid, feedback voltage is more than the set value 9 times. This feedback voltage is used to update PWM for output control.$m$, $m$Charge corona unit defective or disconnected · - Charge corona harness defective · Charge corona power pack is defective.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC320-01$m$, $m$D$m$, $m$Development output abnormal$m$, $m$The high voltage applied to the development unit is detected 10 times higher than the upper limit (45%) of PWM.$m$, $m$Development power pack defective · - Development bias leak due to poor connection, defective · connector$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC324-01$m$, NULL, $m$Development motor lock$m$, $m$The development motor lock signal remains high for 2 seconds while the development motor is on. If this SC is returned on a machine in the field, inspect the toner D supply unit coil. If the gear is not damaged, replace the coil. If the gear is damaged, the gear shaft is probably deformed, so replace the entire unit. Drive mechanism overloaded due to toner clumping in the wasted toner path$m$, $m$Motor driver board defective · TD sensor adjustment error: Adjustment output abnormal · During the TD sensor auto adjustment, the TD sensor output voltage · (Vt) is 2.5 volts or higher even though the control voltage is set to the Service Call · D minimum value (PWM = 0). When this error occurs, SP2-906-1 reads Conditions · 0.00V.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC360-01$m$, NULL, $m$Note: This SC is released only after correct adjustment of the TD$m$, $m$sensor has been achieved. Switching the machine off and on will cancel the SC display, but does not release ID sensor toner supply.$m$, $m$TD sensor defective · TD sensor harness disconnected · TD sensor connector disconnected or defective · - IOB defective · Toner bottle motor defective · Note: When the TD sensor is defective, the toner supply is · controlled using pixel count and the ID sensor.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC360-11$m$, NULL, $m$TD sensor adjustment error: Timeout Error$m$, $m$During the TD sensor auto adjustment, the TD sensor output voltage (Vt) does not enter the target range (3.0 ± 0.1V) within 20 D s. When this error occurs, the display of SP2-906-1 reads 0.00V.$m$, $m$Note: · This SC is released only after correct adjustment of the TD sensor · has been achieved. Switching the machine off and on will cancel · the SC display, but does not release ID sensor toner supply. · TD sensor defective · TD sensor harness disconnected · TD sensor connector disconnected or defective · IOB defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC361-00$m$, $m$C$m$, $m$TD sensor output error: Upper Limit$m$, $m$TD sensor output voltage (Vt), measured during each copy cycle, is detected higher than 4V for 10 prints.$m$, $m$TD sensor defective · TD sensor harness disconnected · TD sensor connector disconnected or defective · - IOB defective · Toner bottle motor defective · Note: When the TD sensor is defective, the toner supply is · controlled using pixel count and the ID sensor.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC362-00$m$, $m$C$m$, $m$TD sensor output error: Lower limit$m$, $m$TD sensor output voltage (Vt), measured during each copy cycle, is detected 10 times lower than 0.5V.$m$, $m$TD sensor defective · TD sensor harness disconnected · TD sensor connector disconnected or defective · - IOB defective · Toner bottle motor defective · Note: When the TD sensor is defective, the toner supply is · controlled using pixel count and the ID sensor. · ID sensor adjustment error: LED output abnormal · One of the following ID sensor output voltages is detected at ID Conditions · sensor initialization.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC370-01$m$, $m$C$m$, $m$Vsg less than 4.0V when the maximum PWM input (255) is$m$, $m$applied to the ID sensor. Vsg greater than or equal to 4.0V when the minimum PWM input (0) is applied to the ID sensor.$m$, $m$ID sensor defective · ID sensor harness disconnected · ID sensor connector defective · IOB defective · ID sensor pattern not written correctly · Incorrect image density · Charge power pack defective · ID sensor dirty · ID sensor adjustment error: Timeout error · C Vsg falls out of the adjustment target (4.0 -0.2V) during Vsg · checking within 20 sec.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC370-11$m$, NULL, $m$ID sensor defective$m$, $m$- ID sensor harness disconnected$m$, $m$ID sensor connector defective · IOB defective · ID sensor pattern not written correctly · Incorrect image density · Charge power pack defective · ID sensor dirty$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC375-00$m$, $m$C$m$, $m$ID sensor error: Drum surface voltage error$m$, $m$The ID sensor output voltage is 5.0V and the PWM signal input to the ID sensor is 0 when checking the ID sensor pattern.$m$, $m$ID sensor defective · ID sensor harness disconnected · ID sensor connector defective · IOB defective · ID sensor pattern not written correctly · Incorrect image density · Charge power pack defective · ID sensor dirty · ID sensor error: Pattern edge detection failed · C For 2 s during the ID sensor pattern check, the ID sensor pattern · edge voltage is not 2.5V or the pattern edge is not detected within · 800 ms.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC376-00$m$, NULL, $m$ID sensor defective$m$, $m$- ID sensor harness disconnected$m$, $m$ID sensor connector defective · IOB defective · ID sensor pattern not written correctly · Incorrect image density · Charge power pack defective · ID sensor dirty$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC377-00$m$, $m$C$m$, $m$ID sensor error: Potential surface reading error$m$, $m$The Vp value, which measures the reflectivity of the ID sensor Conditions pattern, was not in the range of -70V to -400V.$m$, $m$Potential sensor defective · Potential sensor harness defective · Potential sensor disconnected · - IOB defective · OPC unit connector defective · Charge corona power pack defective · Charge corona wire dirty, broken$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC378-00$m$, NULL, $m$ID sensor pattern error$m$, $m$One of the following ID sensor output voltages was detected twice consecutively when checking the ID sensor pattern. C Vsp greater than or equals 2.5V Vsg less than 2.5$m$, $m$Vsp = 0V · Vsg = 0 · ID sensor defective · ID sensor harness disconnected · ID sensor connector defective · IOB defective · ID sensor pattern not written correctly · Incorrect image density · Charge power pack defective · ID sensor dirty$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC380-01$m$, $m$C$m$, $m$Potential sensor calibration error (VM100)$m$, $m$During drum potential sensor calibration, when -100V is applied to the drum, the output value is out of the prescribed range.$m$, $m$Potential sensor defective · Potential sensor harness disconnected · Potential sensor connector defective or disconnected · IOB defective · OPC connector defective · Development power pack defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC380-11$m$, $m$C$m$, $m$Potential sensor calibration error (VM800)$m$, $m$During drum potential sensor calibration, when -800V is applied to the drum, the output value is out of the prescribed range.$m$, $m$Potential sensor defective · Potential sensor harness disconnected · Potential sensor connector defective or disconnected · IOB defective · OPC connector defective · Development power pack defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC380-21$m$, $m$C$m$, $m$Potential sensor calibration error (skew)$m$, $m$During drum potential sensor calibration, the drum potential sensor output voltage does not meet specification when test voltages (-100V, -800V) are applied to the drum.$m$, $m$Potential sensor defective · Potential sensor harness disconnected · Potential sensor connector defective or disconnected · IOB defective · OPC connector defective · Development power pack defective · Potential sensor calibration error (cut off) · C During drum potential sensor calibration, the drum potential sensor · output voltage did not meet specification when test voltages · (-100V, -800V) are applied to the drum.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC380-31$m$, NULL, $m$Potential sensor defective$m$, $m$- Potential sensor harness disconnected Service Call Potential sensor connector defective or disconnected Conditions IOB defective$m$, $m$OPC connector defective · Development power pack defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC380-41$m$, NULL, $m$Potential sensor calibration error (VD)$m$, $m$During drum potential sensor calibration when adjusting the drum potential (VD), the drum potential sensor detects VD higher than VG (grid voltage).$m$, $m$C -or- · When adjusting VD (drum surface potential of black areas after · exposure), even after 5 adjustments of VG (charge corona grid · potential), VD could not be set in the target range (-800±20+ VL + · 130V) · Potential sensor defective · Potential sensor harness disconnected · Potential sensor connector defective or disconnected · - IOB defective · OPC connector defective · Development power pack defective · Charge corona unit worn out, dirty$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC380-51$m$, $m$C$m$, $m$Potential sensor calibration (VL)$m$, $m$During drum potential sensor calibration, when VL is adjusted, the pattern surface potential VL pattern is not within range 0V to -400V. (VL is the potential after exposing a white pattern.) Potential sensor defective$m$, $m$Potential sensor harness disconnected · Potential sensor connector defective or disconnected · - IOB defective · OPC connector defective · Charge corona power pack defective · Development power pack defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC396-01$m$, $m$D$m$, $m$Main motor error$m$, $m$The main motor lock signal remains low for 2 seconds while the main motor is on.$m$, $m$Drive mechanism overloaded · Motor driver board defective$m$, NULL, NULL, NULL);
INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC410-00$m$, $m$C$m$, $m$Quenching lamp error$m$, $m$At the completion of auto process control initialization, the potential Conditions of the drum surface detected by the potential sensor is more than -400V, the prescribed value.$m$, $m$Quenching lamp defective · Quenching lamp harness disconnected · Quenching lamp connector loose, defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC440-01$m$, $m$D$m$, $m$Transfer output abnormal (voltage leak detected)$m$, $m$When the transfer is output, the feedback voltage remains higher than 4V for 60 ms.$m$, $m$Transfer power pack defective · - Transfer current terminal, transfer power pack disconnected, · damaged connector$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC440-02$m$, $m$D$m$, $m$Transfer output abnormal release detection$m$, $m$When the transfer is output, there is hardly any feedback voltage within 60 ms even with application of 24% PWM.$m$, $m$Transfer power pack defective · - Transfer unit harness disconnected · Transfer connector loose, defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC495-00$m$, $m$D$m$, $m$Toner recycling unit error$m$, $m$Encoder pulse does not change for 3 s after the main motor switches on. Waste toner transport has stopped due to motor overload$m$, $m$Toner end sensor detective, disconnected$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC496-00$m$, $m$D$m$, $m$Toner collection bottle error$m$, $m$The toner collection bottle set switch remains off when the front door is closed.$m$, $m$No toner collection bottle set · Poor connection of the switch connector · Tray 1 lift malfunction · The lift sensor is not activated within 10 s after the tray lift motor Conditions · starts lifting the bottom plate.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC501$m$, $m$B$m$, NULL, $m$When the tray lowers, the tray lift sensor does not go off within 1.5 s. Tray overload detected when the tray is set. The lower limit sensor of the LCT does not detect the lower limit within 10 s.$m$, $m$Tray lift motor defective, disconnected · Paper or other obstacle trapped between tray and motor · Pick-up solenoid disconnected, blocked by an obstacle · Too much paper loaded in tray · Note · At first, the machine displays a message asking the operator to$m$, $m$reset the tray. This SC will not display until the operator has pulled the tray out and pushed it in 3 times. If the operator turns the machine off/on before the 3rd opening and closing of the tray, the 3-count is reset. Tray 2 lift malfunction The lift sensor is not activated within 10 s after the tray lift motor$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC502$m$, $m$B$m$, $m$starts lifting the bottom plate.$m$, $m$When the tray lowers, the tray lift sensor does not go off within 1.5 s. Tray overload detected when the tray is set.$m$, $m$Tray lift motor defective or disconnected · Paper or other obstacle trapped between tray and motor · Pick-up solenoid disconnected or blocked by an obstacle · Too much paper loaded in tray · Note · At first, the machine displays a message asking the operator to$m$, $m$reset the tray. This SC will not display until the operator has pulled the tray out and pushed it in 3 times. If the operator turns the machine off/on before the 3rd opening and closing of the tray, the 3-count is reset. Tray 3 lift malfunction The lift sensor is not activated within 10 s after the tray lift motor$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC503$m$, $m$B$m$, $m$starts lifting the bottom plate.$m$, $m$When the tray lowers, the tray lift sensor does not go off within 1.5 s. Tray overload detected when the tray is set. Conditions Tray lift motor defective or disconnected$m$, $m$Paper or other obstacle trapped between tray and motor · Pick-up solenoid disconnected or blocked by an obstacle · Too much paper loaded in tray · Note · At first, the machine displays a message asking the operator to$m$, $m$reset the tray. This SC will not display until the operator has pulled the tray out and pushed it in 3 times. If the operator turns the machine off/on before the 3rd opening and closing of the tray, the 3-count is reset. Tray 4 lift malfunction The lift sensor is not activated within 10 s after the tray lift motor$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC504$m$, $m$B$m$, $m$starts lifting the bottom plate.$m$, $m$When the tray lowers, the tray lift sensor does not go off within 1.5 s. Tray overload detected when the tray is set.$m$, $m$Tray lift motor defective or disconnected · Paper or other obstacle trapped between tray and motor · Pick-up solenoid disconnected or blocked by an obstacle · Too much paper loaded in tray · Note · At first, the machine displays a message asking the operator to$m$, $m$reset the tray. This SC will not display until the operator has pulled the tray out and pushed it in 3 times. If the operator turns the machine off/on before the 3rd opening and closing of the tray, the 3-count is reset. LCT tray malfunction One of the following conditions is detected: When the bottom plate is lifted, the upper limit sensor does not come on for 18 s. When the bottom plate is lowered, the lower limit sensor does not$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC510$m$, $m$B$m$, $m$come on for 18 s.$m$, $m$After lift begins, the upper limit sensor does not switch on before the pick-up solenoid switches on. The paper end sensor switches on during lift and the upper limit sensor does not switch on for 2.5 s, and a message prompts user to reset paper. Tray lift motor defective or connector disconnected Lift sensor defective or disconnected$m$, $m$Pick-up solenoid defective or disconnected · Paper end sensor defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC515-00$m$, $m$C$m$, $m$Duplex jogger motor error 1$m$, $m$When the jogger fence moves to the home position, the jogger HP sensor does not turn on even if the jogger fence motor has moved Service Call the jogger fence 153.5 mm. Conditions$m$, $m$Paper or other obstacle has jammed mechanism · Sensor connector disconnected or defective · Sensor defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC516-00$m$, $m$C$m$, $m$Duplex jogger motor error 2$m$, $m$When the jogger fence moves from the home position, the jogger fence HP sensor does not turn off even if the jogger motor has moved the jogger fence 153.5 mm. Paper or other obstacle has jammed mechanism Sensor connector disconnected or defective$m$, $m$Sensor defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC530-00$m$, $m$D$m$, $m$Main fan error$m$, $m$The main fan motor lock signal goes high for 5 s while the fan is on.$m$, $m$Fan motor overloaded due to obstruction · Fan connector disconnected$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC540-01$m$, $m$D$m$, $m$Fusing exit motor error$m$, $m$The PLL lock signal was low for 2 s during motor operation.$m$, $m$Motor lock caused by physical overload · Motor drive PCB defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC540-02$m$, NULL, $m$Fusing web motor error 1$m$, $m$The amount of current detected during operation of the web motor exceeded 350 mA in 5 successive samples.$m$, $m$D · Motor connection loose, broken, defective · Motor disconnected · Motor lock or short$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC540-03$m$, NULL, $m$Fusing web motor error 2$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC540-04$m$, NULL, $m$Fusing web motor error 3$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC541$m$, $m$A$m$, $m$Fusing thermistor open$m$, $m$The fusing temperature detected by the center thermistor was below 0°C for 7 s.$m$, $m$Thermistor open · Thermistor connector defective · Thermistor damaged, or out of position · Fusing temperature -15% less than the standard input voltage$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC542$m$, $m$A$m$, $m$-001 Fusing temperature warm-up error 1: Center themistor$m$, $m$The center thermistor that touches the hot roller determined that the hot roller failed to reach the warm-up temperature within the Service Call prescribed time. Conditions$m$, $m$Fusing lamp disconnected · Thermistor warped, out of position · Thermostat has opened$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC543$m$, $m$A$m$, $m$Fusing lamp overheat error 1 (software)$m$, $m$Central thermistor detected a temperature of 240°C at the center of the hot roller. Fusing temperature control software error PSU defective$m$, $m$IOB defective · BICU defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC544$m$, $m$A$m$, $m$Fusing lamp overheat error 1: Hardware$m$, $m$The center thermistor or an end thermistor detected a temperature of 250°C on the hot roller.$m$, $m$PSU defective · IOB defective · BICU defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC545$m$, $m$A$m$, $m$Fusing lamp overheat error 2: Center lamp$m$, $m$After hot roller reaches warm-up temperature, the fusing lamps remained on at full capacity for 11 samplings (1.8 s. duration) while the hot roller was not rotating.$m$, $m$Thermistor damaged, or out of position · Fusing lamp disconnected$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC547-01$m$, $m$D$m$, $m$Zero cross signal error 1: Fusing relay$m$, $m$At power on and with the fusing relay off, 3 samplings detected that the zero cross was not normal.$m$, $m$Fusing relay short · Fusing relay drive circuit defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC547-02$m$, $m$D$m$, $m$Zero cross signal error 2: Fusing relay$m$, $m$No zero cross signal was detected within 3 sec. after power on or after closing the front door.$m$, $m$Fusing relay short · Fusing relay drive circuit defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC547-03$m$, $m$D$m$, $m$Zero cross signal error 2: Unstable power supply$m$, $m$After 11 samplings the power supply was not within 50 to 60 Hz, indicating that the power supply is not stable. Service Call$m$, NULL, $m$Check power source with local supplier$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC551$m$, $m$A$m$, $m$Fusing thermistor error 1: End thermistor$m$, $m$The end thermistor (contact type) was less than 0C (32F) for more than 7 seconds.$m$, $m$Thermistor connector loose, broken, defective · Thermistor incorrectly installed or loose$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC552-01$m$, NULL, $m$Fusing reload temperature error 1: End thermistor$m$, $m$The end thermistor (contact type) could not detect: A 100°C 25 seconds after the start of the warm-up cycle. A change in temperature more than 16 degrees for 5 seconds. The reload temperature with 56 seconds after the start of the fusing temperature control cycle.$m$, $m$Fusing lamp disconnected · Thermistor connector loose, broken, defective · Thermistor out of position, installed incorrectly · Thermostat open$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC552-02$m$, $m$A$m$, $m$Fusing reload temperature error 2: End thermistor$m$, $m$The hot roller did not reach 100oC within the prescribed time.$m$, $m$Fusing lamp disconnected · Thermistor connector loose, broken, defective · Thermistor out of position, installed incorrectly · Thermostat open$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC552-03$m$, $m$A$m$, $m$Fusing reload temperature error 3: End thermistor$m$, $m$The hot roller did not reach the prescribed temperature within 3 sec, after the start of the fusing temperature control cycle.$m$, $m$Fusing lamp disconnected · Thermistor connector loose, broken, defective · Thermistor out of position, installed incorrectly · Thermostat open$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC553$m$, $m$A$m$, $m$Fusing thermistor error 4: End thermistor (software)$m$, $m$The end thermistor (contact type) was at 240°C (464±F) for more than 1 second. The temperature is read 10 times every second. (at 0.1 s intervals).$m$, $m$PSU defective · IOB control board defective · BICU control board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC555$m$, $m$A$m$, $m$Fusing lamp error$m$, $m$After the start of the warmup cycle, a fusing lamp was at full power for 1.8 s but the hot roller did not turn.$m$, $m$Thermistor bent, out of position · Fusing lamp disconnected · Circuit breaker opened$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC557$m$, $m$C$m$, $m$Zero cross signal error$m$, $m$High frequency noise was detected on the powe r line. No action required. The SC code is logged and the operation of the machine is not affected.$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC559$m$, $m$A$m$, $m$Fusing jam: 3 counts$m$, $m$At the fusing exit sensor the paper was detected late for three pulse counts (lag error), and SP1159 was on. Service Call If this SC occurs, the machine cannot be used until the service technician cancels the SC code. This SC occurs only if SP1159 has been set to "1" (On). (Default: 0 (Off)).$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC569$m$, $m$D$m$, $m$Fusing pressure release motor error$m$, $m$During copying, the HP sensor could not detect the actuator, tried again 3 times and could not detect. Motor lock because of too much load Motor driver defective$m$, $m$HP sensor defective, disconnected, connector defective, · harness damaged$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC590-00$m$, $m$D$m$, $m$Toner collection motor error$m$, $m$The toner collection motor sensor output does not change for 3 s while the toner collection motor is on.$m$, $m$Motor lock due to obstruction · Motor driver board defective · Motor connection loose, defective · Toner collection motor sensor disconnected, sensor defective · Rotational transmission shaft (dia. x 30) missing$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC620-01$m$, $m$D$m$, $m$BCU-ADF Communication Error: Break RX abnormal$m$, $m$A BREAK was detected after connection. ADF I/F cable connection loose, broken, defective ADF control board defective$m$, $m$BCU defective · Serial line level unstable · External noise on the line$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC620-2$m$, $m$D$m$, $m$BCU-ADF Communication Error: Timeout$m$, $m$ADF I/F cable connection loose, broken, defective ADF control board defective$m$, $m$BCU defective · Serial line level unstable · External noise on the line$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC621-01$m$, $m$D$m$, $m$BICU/Finisher communication error: Break error$m$, $m$During communication with the finisher MBX, the BICU received a break (Low) signal from the finisher. Connection between main machine loose, broken, defective Breaker switch defective$m$, $m$Power cord loose, broken, defective · Peripheral unit control board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC621-02$m$, $m$D$m$, $m$BCU/Finisher communication error: Timeout error$m$, $m$During communication between the finisher MBX and the BCU, no ACK signal was detected for 100 ms, even after three attempts. Service Call Connection between main machine loose, broken, defective Breaker switch defective$m$, $m$Power cord loose, broken, defective · Peripheral unit control board defective · BCU defective · Serial line level unstable, external noise on the line$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC623$m$, $m$D$m$, $m$BCU-PFB communication error$m$, $m$More than 2 in communication errors between the BCU and PFB were detected after startup, or more than 3 errors were detected after settings were initialized. Harness connectors between BCU and PFB loose, broken, disconnected$m$, $m$Serial line connection unstable · External noise on the line · BCU defective · PFB defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC626-01$m$, $m$D$m$, $m$BICU, LCT communication error: Break reception error$m$, $m$During communication with the LCT, the BICU received a break (Low) signal. LCT connection to main machine loose, broken, defective LCT control board defective$m$, $m$BCU defective · Serial line connection unstable · External noise on the line$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC626-02$m$, $m$D$m$, $m$BICU, LCT communication error: Timeout error$m$, $m$After 1 data frame is sent to the LCT, an ACK signal is not received within 100 ms, and is not received after 3 retries. LCT connection to main machine loose, broken, defective LCT control board defective$m$, $m$BCU defective · Serial line connection unstable · External noise on the line$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC632$m$, $m$B$m$, $m$Counter device error 1 CTL$m$, $m$After 3 attempts to send a data frame to the optional counter device via the serial communication line, no ACK signal was received within 100 ms. Serial line between the optional counter device, the relay board and copier control board is disconnected or damaged.$m$, NULL, $m$Make sure that SP5113 is set to enable the optional counter device. Check if the setting of the SP5113 is correctly set. Check the connection between the main machine and optional counter device. Counter device error 2 CTL After communication was established, the controller receivee the brake signal from the accounting device.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC633$m$, NULL, $m$Serial line between the optional counter device, the relay board$m$, $m$and copier control board is disconnected or damaged. B Make sure that SP5113 is set to enable the optional counter device.$m$, NULL, $m$Confirm that the setting of SP5113 is correct. Check the connection between the main machine and optional counter device. Counter device error 3 CTL$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC634$m$, $m$A$m$, $m$backup RAM error was returned by the counter device.$m$, $m$B Counter device control board defective$m$, $m$Backup battery of counter device defective Service Call$m$, $m$Replace the counter device. Counter device error 4 CTL$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC635$m$, $m$A$m$, $m$backup battery error was returned by the counter device.$m$, $m$B Counter device control board defective$m$, $m$Backup battery of counter device defective$m$, $m$Replace the counter device.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC636$m$, $m$D$m$, $m$SD Card Error CTL$m$, $m$01 Expanded authentication module error$m$, $m$There is no expanded authentication module in the machine. · The SD card or the file of the expanded authentication module is · broken. There is no DESS module in the machine. · No expanded authentication module · Defective SD card · Defective file in the authentication module · No DESS module$m$, $m$1. Install the expanded authentication module. 2. Install the SD card. 3. Install the DESS module. 4. In the SSP mode set SP5-401-160 to 0. 5. In the SSP mode, set SP5-401-161 to 0. 6. Cycle the machine off/on. 7. Execute SP5-876-1 (security all clear). 8. If this is a mass-produced machine, replace the NV. 02 Version error The version of the expanded authentication module is not correct. Incorrect module version Install the correct file of the expanded authentication module. 11 OSM user code file error The correct "usercode" file could not be found in the root folder of the SD card because the file is not present, or the existing file is corrupted or the wrong type file. Create the usercode files with the User Setting Tool "IDissuer.exe" . Store the files in the root folder of the SD card. Note: Make sure the eccm.mod file is in the root folder of the SD card.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC637$m$, $m$D$m$, $m$Tracking information notification error CTL$m$, $m$Ttracking application error$m$, $m$Tracking information was lost. The machine failed to give notice of · the tracking information to the tracking SDK application. · Cycle the machine off/on · Management server error · The machine failed to give notice of the tracking information to the · 02 management server. Tracking information was lost, and the machine · could not count correctly. · Cycle the machine off/on$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC640$m$, NULL, $m$Engine-to-Controller Communication Error CTL$m$, $m$This is a checksum error.$m$, $m$D · PCI hardware error · Cycle the machine off/on · Engine serial communication error CTL · An error occurs in serial communication with engine.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC641$m$, $m$D$m$, $m$SC641-1: Timeout error$m$, $m$SC641-2: Retry over$m$, NULL, NULL, NULL, NULL);
INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC641-3$m$, NULL, $m$: Download error Service Call$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC641-4$m$, NULL, $m$: UART error Conditions$m$, $m$Cycle the machine off/on$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC650$m$, $m$B$m$, $m$@Remote communication error (Cumin-M) CTL$m$, $m$The authentication for the Cumin-M fails failed at a dial up connection due to one or more of the following: Incorrect SP settings$m$, $m$Disconnected telephone line · 01 Disconnected modem board · Disconnected wireless LAN card$m$, $m$Check and set the correct user name (SP5-816-156) and password (SP5-816-157). Communication line error The supplied voltage is not sufficient due to the defective communication line or defective connection. The authentication for the Cumin-M fails failed at a dial up connection due to one or more of the following: 04 Incorrect SP settings Disconnected telephone line Disconnected modem board Disconnected wireless LAN card Check and set the correct user name (SP5-816-156) and password (SP5-816-157). 05 No modem board Modem board is not installed even though the setting at Cumin-M (During the operation) The authentication for the Cumin-M fails failed at a dial up connection due to one or more of the following: Incorrect SP settings Disconnected telephone line Disconnected modem board Disconnected wireless LAN card Check and set the correct user name (SP5-816-156) and password (SP5-816-157). Modem board error 1 Modem board not installed or the board is defective. 13 Install the modem board. Check correct setting value for modem driver (SP5-816-160, SP5-816-165 to 171, SP5-816-188 and 189). Replace the modem board. Modem board error 2 Modem board not installed or the board is defective. Uninstall the modem board if it is installed. Check that the wired/wireless LAN is working properly. For more details about this SC code error, execute SP5990 to print an SMC report so you can read the error code. The error code is not displayed on the operation panel. Here is a list of error codes: Error Problem Solution 1 Failure to certify dial-up In the User Tools, check the dial-up user and dial-up password settings 4 Illegal modem setting Check the setting of SP5816 160 to determine whether the setting for the AT command is correct. If Service Call this SP setting is correct, then the problem is a bug in Conditions the software. Poor connection due to low The problem is on the external power supply line, so power supply on the line. there is no corrective action on the machine. Data in the NVRAM became corrupted when Use SP5985 1 and set the NIC to "0" (Disable) to 11 the network enable switch disable the network board. and Cumin-M were enabled at the same time. The modem board could Replace the modem board. not enable the NIB. Illegal Remote Service Dial-up CTL$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC651-01$m$, $m$C$m$, $m$An expected error occurred when Cumin-M dialed up the NRS Center.$m$, $m$Software bug$m$, $m$No action is required because only the count is logged$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC651$m$, $m$C$m$, $m$Incorrect dial up connection CTL$m$, $m$01 - Chat program parameter error$m$, $m$02 - Chat program execution error · An unexpected error occurs when the modem (Cumin-M) tries to call · the center with a dial up connection. · Caused by a software bug · No action required · This SC does not interfere with operation of the machine. · Remote service ID2 mismatching · There was an authentication mismatch between ID2 for @Remote, the · controller board, and NVRAM.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC652$m$, $m$D$m$, $m$Used controller board installed$m$, $m$Used NVRAM installed$m$, $m$An unexpected error occurs when the modem (Embedded RCG-M) · tries to call the center with a dial up connection.$m$, $m$Install the correct controller board or anew controller board. Install the correct NVRAM or new NVRAM. Incorrect remote service ID2 CTL ID2 stored in the NVRAM is incorrect.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC653$m$, $m$D$m$, $m$Used NVRAM installed$m$, $m$An unexpected error occured when the modem (Embedded RCG-M) tries to call the center with a dial up connection Clear the ID2 in the NVRAM$m$, $m$Input the correct ID2. · Engine start up error CTL$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC670$m$, NULL, $m$The BCU failed to respond within the prescribed time when the$m$, $m$machine was turned on. D Connections between BCU and controller board are loose, Service Call$m$, $m$disconnected, or damaged. Conditions$m$, $m$Replace the BCU Replace the controller board Illegal Engine Board CTL$m$, NULL, NULL),
